/*global Chart */

// Standalone analysis page script.
// Loads precomputed outputs from /data/analysis.json (generated by python scripts)
// and renders charts only. No simulator endpoints are called here.

$(document).ready(function () {
    var analysisTempChart;
    var analysisDwellChart;
    var analysisMaterialChart;
    var analysisSpeedupChart;
    var analysisRadarChart;
    var analysisHistogramChart;
    var analysisStabilityChart;
    var analysisRiskChart;

    initCharts();
    loadAnalysis();

    function initCharts() {
        var tempCtx = document.getElementById("analysisTempChart");
        if (tempCtx) {
            analysisTempChart = new Chart(tempCtx, {
                type: 'line',
                data: { datasets: [] },
                options: {
                    responsive: true,
                    animation: { duration: 0 },
                    tooltips: { enabled: true },
                    scales: {
                        yAxes: [{ ticks: { beginAtZero: false, suggestedMin: 0.95, suggestedMax: 1.02 } }],
                        xAxes: [{ type: 'linear', position: 'bottom', ticks: { min: 30, max: 200, stepSize: 20 } }]
                    }
                }
            });
        }

        var dwellCtx = document.getElementById("analysisDwellChart");
        if (dwellCtx) {
            analysisDwellChart = new Chart(dwellCtx, {
                type: 'line',
                data: { datasets: [] },
                options: {
                    responsive: true,
                    animation: { duration: 0 },
                    tooltips: { enabled: true },
                    scales: {
                        yAxes: [{ ticks: { beginAtZero: false, suggestedMin: 0.95, suggestedMax: 1.02 } }],
                        xAxes: [{ type: 'linear', position: 'bottom', ticks: { min: 1, max: 20, stepSize: 2 } }]
                    }
                }
            });
        }

        var matCtx = document.getElementById("analysisMaterialChart");
        if (matCtx) {
            analysisMaterialChart = new Chart(matCtx, {
                type: 'bar',
                data: {
                    labels: [],
                    datasets: [{
                        label: 'Avg Length Factor',
                        data: [],
                        backgroundColor: "rgba(75,192,192,0.5)",
                        borderColor: "rgba(75,192,192,1)",
                        borderWidth: 1
                    }]
                },
                options: {
                    responsive: true,
                    animation: { duration: 0 },
                    scales: { yAxes: [{ ticks: { beginAtZero: false, suggestedMin: 0.85, suggestedMax: 1.10 } }] }
                }
            });
        }

        var radarCtx = document.getElementById("analysisRadarChart");
        if (radarCtx) {
            analysisRadarChart = new Chart(radarCtx, {
                type: 'radar',
                data: { labels: [], datasets: [] },
                options: {
                    responsive: true,
                    animation: { duration: 0 },
                    scale: { ticks: { suggestedMin: 0.85, suggestedMax: 1.10 } }
                }
            });
        }

        var histCtx = document.getElementById("analysisHistogramChart");
        if (histCtx) {
            analysisHistogramChart = new Chart(histCtx, {
                type: 'bar',
                data: { labels: [], datasets: [{
                    label: 'Count',
                    data: [],
                    backgroundColor: "rgba(54,162,235,0.5)",
                    borderColor: "rgba(54,162,235,1)",
                    borderWidth: 1
                }] },
                options: {
                    responsive: true,
                    animation: { duration: 0 },
                    scales: { yAxes: [{ ticks: { beginAtZero: true } }] }
                }
            });
        }

        var stabilityCtx = document.getElementById("analysisStabilityChart");
        if (stabilityCtx) {
            analysisStabilityChart = new Chart(stabilityCtx, {
                type: 'bar',
                data: { labels: [], datasets: [] },
                options: {
                    responsive: true,
                    animation: { duration: 0 },
                    scales: {
                        yAxes: [{ ticks: { beginAtZero: true, suggestedMax: 100 } }],
                        xAxes: [{ stacked: true }]
                    }
                }
            });
        }

        var riskCtx = document.getElementById("analysisRiskChart");
        if (riskCtx) {
            analysisRiskChart = new Chart(riskCtx, {
                type: 'bar',
                data: { labels: [], datasets: [{
                    label: '% below 0.95',
                    data: [],
                    backgroundColor: "rgba(255,99,132,0.5)",
                    borderColor: "rgba(255,99,132,1)",
                    borderWidth: 1
                }] },
                options: {
                    responsive: true,
                    animation: { duration: 0 },
                    scales: { yAxes: [{ ticks: { beginAtZero: true, suggestedMax: 100 } }] }
                }
            });
        }

        var speedCtx = document.getElementById("analysisSpeedupChart");
        if (speedCtx) {
            analysisSpeedupChart = new Chart(speedCtx, {
                type: 'line',
                data: {
                    datasets: [{
                        label: 'Speedup',
                        data: [],
                        borderColor: "rgba(255,99,132,1)",
                        fill: false,
                        pointRadius: 3
                    }]
                },
                options: {
                    responsive: true,
                    animation: { duration: 0 },
                    scales: {
                        yAxes: [{ ticks: { beginAtZero: true, suggestedMax: 8 } }],
                        xAxes: [{ type: 'linear', position: 'bottom', ticks: { beginAtZero: true, stepSize: 1 } }]
                    }
                }
            });
        }
    }

    function loadAnalysis() {
        $.getJSON("/data/analysis_simulation.json", function (data) {
            renderSummary(data);
            renderCharts(data);
        }).fail(function () {
            console.warn("Could not load /data/analysis_simulation.json. Run python analysis scripts to generate it.");
            $("#analysisLoadStatus").text("Missing /data/analysis_simulation.json (run python scripts)");
        });
    }

    function renderSummary(data) {
        if (!data) return;
        if (data.meta) {
            $("#analysisRows").text(data.meta.rows);
            $("#analysisMaterials").text((data.meta.materials || []).length);
        }
        $("#analysisLoadStatus").text("Loaded");
    }

    function renderCharts(data) {
        if (!data || !data.curves) return;

        var colors = [
            "rgba(255,99,132,1)",
            "rgba(54,162,235,1)",
            "rgba(75,192,192,1)",
            "rgba(255,206,86,1)"
        ];

        if (analysisTempChart && data.curves.temperature) {
            var tempSets = [];
            var idx = 0;
            $.each(data.curves.temperature, function (material, points) {
                tempSets.push({
                    label: material,
                    data: points,
                    borderColor: colors[idx % colors.length],
                    fill: false,
                    pointRadius: 0
                });
                idx += 1;
            });
            analysisTempChart.data.datasets = tempSets;
            analysisTempChart.update();
        }

        if (analysisDwellChart && data.curves.dwell) {
            var dwellSets = [];
            var j = 0;
            $.each(data.curves.dwell, function (material, points) {
                dwellSets.push({
                    label: material,
                    data: points,
                    borderColor: colors[j % colors.length],
                    fill: false,
                    pointRadius: 0
                });
                j += 1;
            });
            analysisDwellChart.data.datasets = dwellSets;
            analysisDwellChart.update();
        }

        if (analysisMaterialChart && data.stats) {
            var labels = [];
            var values = [];
            $.each(data.stats, function (material, stat) {
                labels.push(material);
                values.push(stat.mean.length);
            });
            analysisMaterialChart.data.labels = labels;
            analysisMaterialChart.data.datasets[0].data = values;
            analysisMaterialChart.update();
        }

        if (analysisRadarChart && data.simulation && data.simulation.radar) {
            var radar = data.simulation.radar;
            analysisRadarChart.data.labels = radar.labels;
            var radarSets = [];
            var rIdx = 0;
            $.each(radar.materials, function (_, material) {
                var vals = radar.values[material];
                radarSets.push({
                    label: material,
                    data: [vals.length, vals.width, vals.sleeve],
                    borderColor: colors[rIdx % colors.length],
                    backgroundColor: colors[rIdx % colors.length].replace('1)', '0.15)'),
                    fill: true
                });
                rIdx += 1;
            });
            analysisRadarChart.data.datasets = radarSets;
            analysisRadarChart.update();
        }

        if (analysisHistogramChart && data.simulation && data.simulation.histogram) {
            var hist = data.simulation.histogram;
            analysisHistogramChart.data.labels = hist.edges.slice(0, -1).map(function (e, i) {
                return e.toFixed(2) + "–" + hist.edges[i + 1].toFixed(2);
            });
            analysisHistogramChart.data.datasets[0].data = hist.counts;
            analysisHistogramChart.update();
        }

        if (analysisStabilityChart && data.simulation && data.simulation.stability) {
            var stability = data.simulation.stability;
            var tempBins = stability.temperatures;
            var dwellBins = stability.dwellTimes;
            var labels = tempBins.slice(0, -1).map(function (t, i) { return t + "–" + tempBins[i + 1]; });
            var datasets = [];
            for (var j = 0; j < dwellBins.length - 1; j++) {
                datasets.push({
                    label: dwellBins[j] + "–" + dwellBins[j + 1] + " min",
                    data: stability.values[j],
                    backgroundColor: "rgba(75,192,192," + (0.15 + j * 0.1) + ")"
                });
            }
            analysisStabilityChart.data.labels = labels;
            analysisStabilityChart.data.datasets = datasets;
            analysisStabilityChart.update();
        }

        if (analysisRiskChart && data.simulation && data.simulation.riskIndex) {
            var riskLabels = [];
            var riskValues = [];
            $.each(data.simulation.riskIndex, function (material, value) {
                riskLabels.push(material);
                riskValues.push(value);
            });
            analysisRiskChart.data.labels = riskLabels;
            analysisRiskChart.data.datasets[0].data = riskValues;
            analysisRiskChart.update();
        }

        if (analysisSpeedupChart && data.scaling) {
            var pts = [];
            for (var k = 0; k < data.scaling.length; k++) {
                pts.push({ x: data.scaling[k].workers, y: data.scaling[k].speedup });
            }
            analysisSpeedupChart.data.datasets[0].data = pts;
            analysisSpeedupChart.update();
        }
    }
});
